<?php namespace App\Models;use Illuminate\Database\Eloquent\Model;class Payout extends Model{protected $fillable=['seller_id','amount_minor','status','method','reference','reason','reviewed_by','reviewed_at','paid_at','logistics_provider_id','logistics_hub_id','settled_by','receiver_name','proof_note'];protected function casts():array{return['amount_minor'=>'integer','reviewed_at'=>'datetime','paid_at'=>'datetime'];}public function seller(){return $this->belongsTo(Seller::class);} public function provider(){return $this->belongsTo(LogisticsProvider::class,'logistics_provider_id');} public function hub(){return $this->belongsTo(LogisticsHub::class,'logistics_hub_id');} }
